"""Rigs a mesh generated by Hyper3D Rodin that is not a humanoid (the Bull of Heaven, the Scorpion Man).

    blender -b --python models-src/rodin_rig_creature.py -- rodin.glb out.glb models-src/rodin/<npc_id>.json

Like rodin_rig.py the mesh is scaled, stood on the floor, decimated and given a single base-colour texture, but the
skeleton comes from the JSON file: `bones` {name: [head, tail, parent]} in metres (+X is the creature's left, the creature
looks along -Y, z up), `legs` [[upper, lower, "F"|"R", side]] and `tail` [bone names]. Weights follow the distance to the
bones (each vertex belongs mostly to the nearest bone), which suits a body made of limbs and plates. The clips are
Idle and Walk, as for every other model; `kind` selects the gait ("quadruped", "scorpion").
"""
import json
import math
import os
import sys

import bmesh
import bpy
from mathutils import Vector

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)

from chargen import humanoid  # noqa: E402
from chargen.core import reset_scene  # noqa: E402

args = sys.argv[sys.argv.index("--") + 1:]
SRC, OUT = args[0], os.path.abspath(args[1])
CONFIG = json.load(open(args[2]))
NAME = CONFIG["name"]
HEIGHT = CONFIG["height"]          # of the whole mesh, horns and tail included
TRIS = CONFIG.get("tris", 30000)
TEX = CONFIG.get("tex", 2048)
SHIFT = CONFIG.get("shift", [0.0, 0.0])   # moves the bounding-box centre (x, y) to the middle of the body
YAW = CONFIG.get("yaw_deg", 0.0)    # turn so that the creature looks along -Y
BONES = {k: (tuple(v[0]), tuple(v[1]), v[2]) for k, v in CONFIG["bones"].items()}
LEGS = CONFIG.get("legs", [])
TAIL = CONFIG.get("tail", [])
KIND = CONFIG.get("kind", "quadruped")
POWER = CONFIG.get("power", 4.0)    # how sharply a vertex belongs to its nearest bone
INFLUENCES = 4
STAY = CONFIG.get("stay", {})       # {bone: [[axis, lo, hi]...]} boxes whose vertices stay rigidly on that bone


def import_mesh():
    reset_scene()
    bpy.ops.import_scene.gltf(filepath=SRC)
    meshes = [o for o in bpy.context.scene.objects if o.type == "MESH"]
    body = max(meshes, key=lambda o: len(o.data.polygons))
    for o in list(bpy.context.scene.objects):
        if o is not body:
            bpy.data.objects.remove(o, do_unlink=True)
    body.parent = None
    bpy.context.view_layer.objects.active = body
    body.select_set(True)
    bpy.ops.object.transform_apply(location=True, rotation=True, scale=True)
    return body


def normalise(body):
    from mathutils import Matrix
    rot = Matrix.Rotation(math.radians(YAW), 3, "Z")
    co = [rot @ v.co for v in body.data.vertices]
    zmin, zmax = min(c.z for c in co), max(c.z for c in co)
    s = HEIGHT / (zmax - zmin)
    cx = (min(c.x for c in co) + max(c.x for c in co)) / 2 + SHIFT[0] / s
    cy = (min(c.y for c in co) + max(c.y for c in co)) / 2 + SHIFT[1] / s
    for v, c in zip(body.data.vertices, co):
        v.co = Vector(((c.x - cx) * s, (c.y - cy) * s, (c.z - zmin) * s))
    body.data.update()


def decimate(body):
    bm = bmesh.new()
    bm.from_mesh(body.data)
    bmesh.ops.remove_doubles(bm, verts=bm.verts, dist=0.0005)
    bm.to_mesh(body.data)
    bm.free()
    before = len(body.data.polygons)
    if before > TRIS:
        mod = body.modifiers.new("dec", "DECIMATE")
        mod.ratio = TRIS / before
        bpy.ops.object.modifier_apply(modifier=mod.name)
    print("faces", before, "->", len(body.data.polygons))


def simplify_material(body):
    """Every material keeps only its base-colour texture, reduced to TEX px (two materials: TEX // 2 each... the Rodin maps weigh MiBs)."""
    mats = list(body.data.materials)
    size = TEX if len(mats) == 1 else TEX * 3 // 4
    new = []
    for src in mats:
        bsdf = next(n for n in src.node_tree.nodes if n.type == "BSDF_PRINCIPLED")
        link = bsdf.inputs["Base Color"].links
        image = link[0].from_node.image if link and link[0].from_node.type == "TEX_IMAGE" else None
        mat = bpy.data.materials.new("rodin_" + src.name)
        mat.use_nodes = True
        nodes, links = mat.node_tree.nodes, mat.node_tree.links
        out = nodes["Principled BSDF"]
        if image is not None:
            image.scale(size, size)
            tex = nodes.new("ShaderNodeTexImage")
            tex.image = image
            links.new(tex.outputs["Color"], out.inputs["Base Color"])
        out.inputs["Roughness"].default_value = 0.65
        out.inputs["Metallic"].default_value = 0.0
        new.append(mat)
    for i, mat in enumerate(new):
        body.data.materials[i] = mat
    for img in list(bpy.data.images):
        if img.users == 0:
            bpy.data.images.remove(img)


def segment_distance(head, tail, p):
    a, b = Vector(head), Vector(tail)
    ab = b - a
    t = max(0.0, min(1.0, (p - a).dot(ab) / max(ab.length_squared, 1e-9)))
    return (p - (a + ab * t)).length


def skin(body, arm):
    names = [n for n in BONES if n not in ("Root", "Head_end")]
    groups = {n: body.vertex_groups.new(name=n) for n in BONES}
    for v in body.data.vertices:
        ds = {n: segment_distance(BONES[n][0], BONES[n][1], v.co) for n in names}
        raw = {n: 1.0 / (d + 0.03) ** POWER for n, d in ds.items()}
        top = sorted(raw.items(), key=lambda kv: -kv[1])[:INFLUENCES]
        total = sum(w for _, w in top)
        for n, w in top:
            if w / total > 0.01:
                groups[n].add([v.index], w / total, "REPLACE")
    for bone, boxes in STAY.items():
        for v in body.data.vertices:
            if any(all(lo <= v.co["xyz".index(ax)] <= hi for ax, lo, hi in box) for box in boxes):
                for g in list(v.groups):
                    body.vertex_groups[g.group].remove([v.index])
                groups[bone].add([v.index], 1.0, "REPLACE")
    body.parent = arm
    mod = body.modifiers.new("Armature", "ARMATURE")
    mod.object = arm


def animations(arm):
    two_pi = 2 * math.pi
    rot = humanoid.local_rot
    amp = CONFIG.get("gait", {})
    swing_amp = amp.get("swing", 0.38)
    lift_amp = amp.get("lift", 0.6)

    def walk(t):
        d = {}
        a = two_pi * t
        for up, low, group, s in LEGS:
            if KIND == "quadruped":
                phase = 0.0 if (group == "F") == (s == 1) else 0.5
            else:  # scorpion: alternating tetrapod gait, pair index in the group
                phase = ((int(group) % 2) * 0.5 + (0.0 if s == 1 else 0.5)) % 1.0
            tt = (t + phase) % 1.0
            sw, lift = math.sin(two_pi * tt), max(0.0, math.cos(two_pi * tt))
            if KIND == "quadruped":
                d[up] = (rot(arm, up, ("X", -swing_amp * sw)), None)
                d[low] = (rot(arm, low, ("X", lift_amp * lift if group == "F" else -0.5 * lift)), None)
            else:
                d[up] = (rot(arm, up, ("Z", 0.28 * sw * s), ("X", -0.35 * lift)), None)
                d[low] = (rot(arm, low, ("X", 0.4 * lift)), None)
        for k, n in enumerate(TAIL):
            d[n] = (rot(arm, n, ("Z", 0.22 * math.sin(a + k * 0.5)), ("X", 0.04 * math.sin(a + k * 0.5))), None)
        if KIND == "quadruped":
            d["Hips"] = ((0, 0, 0), (0, amp.get("bob", 0.03) * math.cos(2 * a), 0))
            d["Spine"] = (rot(arm, "Spine", ("Z", 0.04 * math.sin(a))), None)
            d["Neck"] = (rot(arm, "Neck", ("X", 0.05 * math.sin(2 * a)), ("Z", -0.05 * math.sin(a))), None)
            d["Head"] = (rot(arm, "Head", ("X", -0.05 * math.sin(2 * a))), None)
        else:
            d["Hips"] = ((0, 0, 0), (0, 0.02 * math.cos(2 * a), 0))
            d["Chest"] = (rot(arm, "Chest", ("Z", 0.05 * math.sin(a))), None)
            d["Head"] = (rot(arm, "Head", ("X", 0.03 * math.sin(2 * a))), None)
            for side, s in (("L", 1), ("R", -1)):
                d["UpperArm_" + side] = (rot(arm, "UpperArm_" + side, ("X", 0.3 * math.sin(a + (0 if s == 1 else math.pi)))), None)
        return d

    def idle(t):
        a = two_pi * t
        d = {"Hips": ((0, 0, 0), (0, 0.006 * math.sin(a), 0))}
        d["Chest"] = (rot(arm, "Chest", ("X", 0.012 * math.sin(a))), None)
        d["Head"] = (rot(arm, "Head", ("X", 0.05 * math.sin(a - 0.5)), ("Z", 0.08 * math.sin(a))), None)
        for k, n in enumerate(TAIL):
            d[n] = (rot(arm, n, ("Z", 0.2 * math.sin(a * 2 + k * 0.7)), ("X", 0.05 * math.sin(a + k * 0.45))), None)
        if KIND != "quadruped":
            for side, s in (("L", 1), ("R", -1)):
                d["UpperArm_" + side] = (rot(arm, "UpperArm_" + side, ("X", 0.03 * math.sin(a + s))), None)
        return d
    humanoid.make_action(arm, "Idle", 72, idle)
    humanoid.make_action(arm, "Walk", 28, walk)


def main():
    body = import_mesh()
    normalise(body)
    decimate(body)
    simplify_material(body)
    body.name = NAME
    arm = humanoid.make_armature(NAME + "_Armature", BONES)
    skin(body, arm)
    bpy.context.view_layer.objects.active = arm
    animations(arm)
    os.makedirs(os.path.dirname(OUT), exist_ok=True)
    humanoid.export_glb(OUT)
    print("exported", OUT, os.path.getsize(OUT))


main()
